package com.geofferwebhook;

import lombok.Value;

@Value
public class GeEventPayload
{
    public static final String SCHEMA = "merch-ge/1";

    String schema;
    long tsMs;
    long accountHash;
    String player;
    String accountType;
    int slot;
    String state;
    int itemId;
    String itemName;
    int price;
    int totalQty;
    int qtySold;
    int spent;
    boolean login;

    public static GeEventPayload of(int slot, String state, int itemId, String itemName,
                                    int price, int totalQty, int qtySold, int spent,
                                    Identity id, long tsMs, boolean login)
    {
        return new GeEventPayload(
            SCHEMA, tsMs, id.getAccountHash(), id.getPlayer(), id.getAccountType(),
            slot, state, itemId, itemName == null ? "" : itemName,
            price, totalQty, qtySold, spent, login);
    }
}

