}

package com.geofferwebhook;

import com.google.gson.FieldNamingPolicy;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Player;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
    name = "GE Offer Webhook",
    description = "Posts a webhook on every Grand Exchange offer change",
    tags = {"grand exchange", "ge", "webhook"}
)
public class GeOfferWebhookPlugin extends Plugin
{
    private static final int LOGIN_BURST_TICKS = 2;

    @Inject private Client client;
    @Inject private ItemManager itemManager;
    @Inject private ClientThread clientThread;
    @Inject private OkHttpClient okHttpClient;
    @Inject private Gson gson;
    @Inject private GeOfferWebhookConfig config;

    private final OfferTracker tracker = new OfferTracker();
    private WebhookClient webhook;
    private int lastLoginTick = -1;

    @Provides
    GeOfferWebhookConfig provideConfig(ConfigManager cm) { return cm.getConfig(GeOfferWebhookConfig.class); }

    @Override
    protected void startUp()
    {
        webhook = new WebhookClient(okHttpClient,
            gson.newBuilder().setFieldNamingPolicy(FieldNamingPolicy.LOWER_CASE_WITH_UNDERSCORES).create());
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invokeLater(this::sendSnapshot);
        }
    }

    @Override
    protected void shutDown()
    {
        webhook = null;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged e)
    {
        switch (e.getGameState())
        {
            case LOGGING_IN:
            case HOPPING:
            case CONNECTION_LOST:
                lastLoginTick = client.getTickCount();
                tracker.reset(); // login replay re-emits slot states; the relay dedups
                break;
            default:
                break;
        }
    }

    @Subscribe
    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged e)
    {
        if (!config.enabled())
        {
            return;
        }
        boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
        boolean login = client.getTickCount() <= lastLoginTick + LOGIN_BURST_TICKS;
        GrandExchangeOffer o = e.getOffer();
        String name = o.getItemId() > 0 ? itemManager.getItemComposition(o.getItemId()).getName() : "";
        tracker.observe(e.getSlot(), wrap(o), name, identity(),
                System.currentTimeMillis(), loggedIn, login)
            .ifPresent(p -> webhook.send(config.webhookUrl(), p));
    }

    private void sendSnapshot()
    {
        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        if (offers == null)
        {
            return;
        }
        OfferView[] views = new OfferView[offers.length];
        String[] names = new String[offers.length];
        for (int i = 0; i < offers.length; i++)
        {
            GrandExchangeOffer o = offers[i];
            views[i] = o == null ? wrapEmpty() : wrap(o);
            names[i] = (o != null && o.getItemId() > 0)
                ? itemManager.getItemComposition(o.getItemId()).getName() : "";
        }
        List<GeEventPayload> out = tracker.snapshot(views, names, identity(), System.currentTimeMillis());
        for (GeEventPayload p : out)
        {
            webhook.send(config.webhookUrl(), p);
        }
    }

    private Identity identity()
    {
        Player p = client.getLocalPlayer();
        String name = p != null && p.getName() != null ? p.getName() : "";
        return new Identity(client.getAccountHash(), name, "NORMAL");
    }

    private static OfferView wrap(GrandExchangeOffer o)
    {
        return new OfferView()
        {
            public String state() { GrandExchangeOfferState s = o.getState(); return s == null ? "EMPTY" : s.name(); }
            public int itemId() { return o.getItemId(); }
            public int quantitySold() { return o.getQuantitySold(); }
            public int totalQuantity() { return o.getTotalQuantity(); }
            public int price() { return o.getPrice(); }
            public int spent() { return o.getSpent(); }
        };
    }

    private static OfferView wrapEmpty()
    {
        return new OfferView()
        {
            public String state() { return "EMPTY"; }
            public int itemId() { return 0; }
            public int quantitySold() { return 0; }
            public int totalQuantity() { return 0; }
            public int price() { return 0; }
            public int spent() { return 0; }
        };
    }
}

