package com.geofferwebhook;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Per-slot GE state, pure and single-threaded (called only from the client thread).
 * Turns raw offer observations into webhook payloads, suppressing duplicates
 * (RuneLite bug #12037) and the login EMPTY burst, and rebuilds state via snapshot().
 */
public class OfferTracker
{
    /** Last-emitted identity per slot, for dedup + reuse detection. */
    private final Map<Integer, GeEventPayload> lastSent = new HashMap<>();

    public Optional<GeEventPayload> observe(int slot, OfferView offer, String itemName,
                                            Identity id, long tsMs, boolean loggedIn, boolean login)
    {
        if ("EMPTY".equals(offer.state()))
        {
            if (loggedIn)
            {
                lastSent.remove(slot); // real slot clear -> forget so reuse isn't deduped
            }
            return Optional.empty();   // EMPTY never becomes an OfferEvent
        }
        GeEventPayload p = GeEventPayload.of(
            slot, offer.state(), offer.itemId(), itemName, offer.price(),
            offer.totalQuantity(), offer.quantitySold(), offer.spent(), id, tsMs, login);
        GeEventPayload prev = lastSent.get(slot);
        if (prev != null && sameEvent(prev, p))
        {
            return Optional.empty();   // duplicate burst (#12037)
        }
        lastSent.put(slot, p);
        return Optional.of(p);
    }

    public List<GeEventPayload> snapshot(OfferView[] offers, String[] itemNames,
                                         Identity id, long tsMs)
    {
        List<GeEventPayload> out = new ArrayList<>();
        for (int slot = 0; slot < offers.length; slot++)
        {
            OfferView o = offers[slot];
            String state = o == null ? "EMPTY" : o.state();
            // Terminal (BOUGHT/SOLD/CANCELLED) offers are re-emitted on
            // purpose: the relay's SlotScreen drops exact replays, and a
            // re-emit is the only way a completion whose original webhook
            // was lost ever reaches the server. gestate's fill_delta keeps
            // its baseline after completion, so no ledger double-count.
            // (Requires the relay's screen — deploy the server first.)
            if ("EMPTY".equals(state))
            {
                lastSent.remove(slot);
                continue;
            }
            observe(slot, o, itemNames[slot], id, tsMs, true, true).ifPresent(out::add);
        }
        return out;
    }

    private static boolean sameEvent(GeEventPayload a, GeEventPayload b)
    {
        return a.getState().equals(b.getState())
            && a.getItemId() == b.getItemId()
            && a.getPrice() == b.getPrice()
            && a.getTotalQty() == b.getTotalQty()
            && a.getQtySold() == b.getQtySold()
            && a.getSpent() == b.getSpent();
    }

    /**
     * Forget per-slot dedup state so the next login replay re-emits current
     * slot states. The relay's SlotScreen owns replay dedup; re-sending is
     * how completions whose webhook was lost get recovered.
     */
    public void reset()
    {
        lastSent.clear();
    }
}

package com.geofferwebhook;

/** Feed-agnostic view of a GE offer slot (decouples the tracker from RuneLite types). */
public interface OfferView
{
    String state();       // GrandExchangeOfferState.name()
    int itemId();
    int quantitySold();
    int totalQuantity();
    int price();
    int spent();
}

package com.geofferwebhook;

import com.google.gson.Gson;
import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/** Fire-and-forget JSON POST of a GE event. Never blocks the client thread. */
@Slf4j
public class WebhookClient
{
    private static final MediaType JSON = MediaType.get("application/json");
    private final OkHttpClient http;
    private final Gson gson;

    public WebhookClient(OkHttpClient http, Gson gson)
    {
        this.http = http;
        this.gson = gson;
    }

    public void send(String url, GeEventPayload payload)
    {
        if (url == null || url.trim().isEmpty())
        {
            return;
        }
        Request request;
        try
        {
            request = new Request.Builder()
                .url(url.trim())
                .post(RequestBody.create(JSON, gson.toJson(payload)))
                .build();
        }
        catch (IllegalArgumentException e)
        {
            log.warn("bad webhook url, dropping event: {}", e.getMessage());
            return;
        }
        http.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.warn("GE webhook delivery failed: {}", e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response r = response)
                {
                    if (!r.isSuccessful())
                    {
                        log.warn("GE webhook non-2xx: {}", r.code());
                    }
                }
            }
        });
    }
}

package com.geofferwebhook;

import com.google.gson.FieldNamingPolicy;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.Test;
import static org.junit.Assert.*;

public class GeEventPayloadTest
{
    private static final Identity ID = new Identity(1234567890123L, "Zezima", "NORMAL");
    private static final Gson GSON = new GsonBuilder()
        .setFieldNamingPolicy(FieldNamingPolicy.LOWER_CASE_WITH_UNDERSCORES)
        .create();

    @Test
    public void serializesToContractSchema()
    {
        GeEventPayload p = GeEventPayload.of(
            3, "SOLD", 314, "Feather", 3, 200, 200, 600, ID, 1784000000000L, false);
        JsonObject j = new JsonParser().parse(GSON.toJson(p)).getAsJsonObject();

        assertEquals("merch-ge/1", j.get("schema").getAsString());
        assertEquals(1784000000000L, j.get("ts_ms").getAsLong());
        assertEquals(1234567890123L, j.get("account_hash").getAsLong());
        assertEquals("Zezima", j.get("player").getAsString());
        assertEquals("NORMAL", j.get("account_type").getAsString());
        assertEquals(3, j.get("slot").getAsInt());
        assertEquals("SOLD", j.get("state").getAsString());
        assertEquals(314, j.get("item_id").getAsInt());
        assertEquals("Feather", j.get("item_name").getAsString());
        assertEquals(3, j.get("price").getAsInt());
        assertEquals(200, j.get("total_qty").getAsInt());
        assertEquals(200, j.get("qty_sold").getAsInt());
        assertEquals(600, j.get("spent").getAsInt());
        assertFalse(j.get("login").getAsBoolean());
    }

    @Test
    public void schemaConstantIsFixed()
    {
        assertEquals("merch-ge/1", GeEventPayload.SCHEMA);
    }
}

