package com.geofferwebhook;

import java.util.List;
import java.util.Optional;
import org.junit.Test;
import static org.junit.Assert.*;

public class OfferTrackerTest
{
    private static final Identity ID = new Identity(1L, "Z", "NORMAL");

    /** Minimal OfferView test double. */
    static OfferView view(String state, int itemId, int qtySold, int total, int price, int spent)
    {
        return new OfferView() {
            public String state() { return state; }
            public int itemId() { return itemId; }
            public int quantitySold() { return qtySold; }
            public int totalQuantity() { return total; }
            public int price() { return price; }
            public int spent() { return spent; }
        };
    }

    @Test
    public void placementEmitsWithZeroFilled()
    {
        OfferTracker t = new OfferTracker();
        Optional<GeEventPayload> p = t.observe(0, view("BUYING", 314, 0, 200, 3, 0),
            "Feather", ID, 100L, true, false);
        assertTrue(p.isPresent());
        assertEquals("BUYING", p.get().getState());
        assertEquals(0, p.get().getQtySold());
        assertFalse(p.get().isLogin());
    }

    @Test
    public void partialThenCompletionBothEmit()
    {
        OfferTracker t = new OfferTracker();
        t.observe(0, view("BUYING", 314, 0, 200, 3, 0), "Feather", ID, 1L, true, false);
        assertTrue(t.observe(0, view("BUYING", 314, 50, 200, 3, 150), "Feather", ID, 2L, true, false).isPresent());
        assertTrue(t.observe(0, view("BOUGHT", 314, 200, 200, 3, 600), "Feather", ID, 3L, true, false).isPresent());
    }

    @Test
    public void duplicateEventIsSuppressed_bug12037()
    {
        OfferTracker t = new OfferTracker();
        OfferView cancel = view("CANCELLED_BUY", 314, 50, 200, 3, 150);
        assertTrue(t.observe(2, cancel, "Feather", ID, 1L, true, false).isPresent());
        // identical repeat (the duplicate CANCELLED_* burst) -> suppressed
        assertFalse(t.observe(2, cancel, "Feather", ID, 2L, true, false).isPresent());
    }

    @Test
    public void reusedSlotWithNewItemEmits()
    {
        OfferTracker t = new OfferTracker();
        t.observe(0, view("BOUGHT", 314, 200, 200, 3, 600), "Feather", ID, 1L, true, false);
        // slot cleared then a new offer for a different item appears
        assertFalse(t.observe(0, view("EMPTY", 0, 0, 0, 0, 0), "", ID, 2L, true, false).isPresent());
        assertTrue(t.observe(0, view("BUYING", 21902, 0, 5, 100, 0), "Dragon crossbow", ID, 3L, true, false).isPresent());
    }

    @Test
    public void emptyBeforeLoginIsNoise()
    {
        OfferTracker t = new OfferTracker();
        // login EMPTY burst arrives while not yet LOGGED_IN -> nothing emitted
        assertFalse(t.observe(0, view("EMPTY", 0, 0, 0, 0, 0), "", ID, 1L, false, false).isPresent());
    }

    @Test
    public void snapshotEmitsLoginFlaggedForNonEmptySlotsOnly()
    {
        OfferTracker t = new OfferTracker();
        OfferView[] offers = {
            view("SELLING", 314, 50, 200, 3, 150),   // slot 0 active
            view("EMPTY", 0, 0, 0, 0, 0),            // slot 1 empty -> skipped
        };
        String[] names = {"Feather", ""};
        List<GeEventPayload> out = t.snapshot(offers, names, ID, 500L);
        assertEquals(1, out.size());
        assertTrue(out.get(0).isLogin());
        assertEquals(0, out.get(0).getSlot());
    }

    @Test
    public void snapshotReEmitsTerminalOffers()
    {
        OfferTracker t = new OfferTracker();
        OfferView[] offers = {
            view("BOUGHT", 314, 200, 200, 3, 600),
            view("SELLING", 2, 1, 5, 10, 10),
            null,
        };
        String[] names = {"Feather", "Cannonball", ""};
        List<GeEventPayload> out = t.snapshot(offers, names, ID, 500L);
        // terminal offers are re-emitted on purpose: the relay's SlotScreen
        // drops exact replays, and a re-emit is the only recovery path for a
        // completion whose original webhook was lost
        assertEquals(2, out.size());
        assertEquals("BOUGHT", out.get(0).getState());
        assertTrue(out.get(0).isLogin());
    }

    @Test
    public void snapshotSeedsDedupSoFirstLiveRepeatIsSuppressed()
    {
        OfferTracker t = new OfferTracker();
        OfferView[] offers = { view("SELLING", 314, 50, 200, 3, 150) };
        t.snapshot(offers, new String[]{"Feather"}, ID, 1L);
        // identical live event right after login is a duplicate of the snapshot
        assertFalse(t.observe(0, view("SELLING", 314, 50, 200, 3, 150), "Feather", ID, 2L, true, false).isPresent());
    }

    @Test
    public void resetForgetsDedupSoLoginReplayResends()
    {
        OfferTracker t = new OfferTracker();
        OfferView sold = view("SOLD", 314, 200, 200, 3, 600);
        assertTrue(t.observe(1, sold, "Feather", ID, 1L, true, false).isPresent());
        // hop/relogin: RuneLite re-fires every slot; without reset() the replay
        // would be swallowed as a duplicate and a lost webhook stays lost
        t.reset();
        assertTrue(t.observe(1, sold, "Feather", ID, 2L, true, true).isPresent());
    }

    @Test
    public void sameItemReusedInSlotAfterEmptyStillEmits()
    {
        OfferTracker t = new OfferTracker();
        // first buy of 5 Feather @3 completes in slot 0
        assertTrue(t.observe(0, view("BOUGHT", 314, 5, 5, 3, 15), "Feather", ID, 1L, true, false).isPresent());
        // slot cleared (collected) while logged in
        assertFalse(t.observe(0, view("EMPTY", 0, 0, 0, 0, 0), "", ID, 2L, true, false).isPresent());
        // an identical new buy of the same item/price/qty in the same slot must NOT be deduped away
        assertTrue(t.observe(0, view("BOUGHT", 314, 5, 5, 3, 15), "Feather", ID, 3L, true, false).isPresent());
    }

    @Test
    public void emptyWhileNotLoggedInPreservesDedupState()
    {
        OfferTracker t = new OfferTracker();
        assertTrue(t.observe(0, view("SELLING", 314, 50, 200, 3, 150), "Feather", ID, 1L, true, false).isPresent());
        // client-reset EMPTY burst while NOT logged in must not clear lastSent
        assertFalse(t.observe(0, view("EMPTY", 0, 0, 0, 0, 0), "", ID, 2L, false, false).isPresent());
        // the same in-progress tuple re-synced from the server is a duplicate -> suppressed
        assertFalse(t.observe(0, view("SELLING", 314, 50, 200, 3, 150), "Feather", ID, 3L, true, false).isPresent());
    }
}

package com.geofferwebhook;

import com.google.gson.FieldNamingPolicy;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.sun.net.httpserver.HttpServer;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.*;

public class WebhookClientTest
{
    private static final Identity ID = new Identity(1L, "Z", "NORMAL");
    private static final Gson TEST_GSON = new GsonBuilder()
        .setFieldNamingPolicy(FieldNamingPolicy.LOWER_CASE_WITH_UNDERSCORES)
        .create();

    @Test
    public void postsJsonBodyToUrl() throws Exception
    {
        CountDownLatch latch = new CountDownLatch(1);
        String[] capturedMethod = new String[1];
        String[] capturedBody = new String[1];

        HttpServer server = HttpServer.create(new InetSocketAddress(0), 0);
        server.createContext("/hook/tok", exchange -> {
            capturedMethod[0] = exchange.getRequestMethod();
            try (InputStream is = exchange.getRequestBody())
            {
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                byte[] buf = new byte[4096];
                int n;
                while ((n = is.read(buf)) != -1)
                {
                    baos.write(buf, 0, n);
                }
                capturedBody[0] = baos.toString(StandardCharsets.UTF_8.name());
            }
            exchange.sendResponseHeaders(204, -1);
            exchange.close();
            latch.countDown();
        });
        server.start();
        try
        {
            int port = server.getAddress().getPort();
            WebhookClient client = new WebhookClient(new OkHttpClient(), TEST_GSON);
            GeEventPayload p = GeEventPayload.of(
                3, "SOLD", 314, "Feather", 3, 200, 200, 600, ID, 1784000000000L, false);
            client.send("http://localhost:" + port + "/hook/tok", p);

            assertTrue("webhook request did not arrive in time", latch.await(5, TimeUnit.SECONDS));
            assertEquals("POST", capturedMethod[0]);
            JsonObject j = new JsonParser().parse(capturedBody[0]).getAsJsonObject();
            assertEquals("merch-ge/1", j.get("schema").getAsString());
            assertEquals(314, j.get("item_id").getAsInt());
        }
        finally
        {
            server.stop(0);
        }
    }

    @Test
    public void blankUrlIsNoOp()
    {
        // must not throw
        new WebhookClient(new OkHttpClient(), TEST_GSON).send("", GeEventPayload.of(
            0, "BUYING", 1, "x", 1, 1, 0, 0, ID, 1L, false));
    }
}
